private enum CrossUiGeneratedKeyboard {
    case email
    case number
    case phone
    case url
}

private extension View {
    @ViewBuilder
    func crossUiKeyboard(_ keyboard: CrossUiGeneratedKeyboard) -> some View {
#if os(iOS)
        switch keyboard {
        case .email:
            keyboardType(.emailAddress)
        case .number:
            keyboardType(.numberPad)
        case .phone:
            keyboardType(.phonePad)
        case .url:
            keyboardType(.URL)
        }
#else
        self
#endif
    }
}
